using System.Numerics;
using System.Text.Json;
using FighterPort.Core;

internal static class EditorControlChecks
{
    public static async Task NativeAsync(string inputPath,string output,Action<bool,string> check)
    {
        var original=await ProjectStore.LoadAsync(inputPath);var clip=original.Clips.First(c=>c.Source?.NativeName=="Wait1");var setup=FighterPort.Adapters.Brawl.BrawlControlProfiles.SetUp(original);int body=ContactSolver.BodyBone(original.Scene,setup);setup=setup with{BodyBone=body};var source=original with{Clips=[clip],ControlRigs=[setup]};var doc=new EditorDocument(source);doc.SelectedBone=body;var before=doc.Evaluate();var native=AnimationControls.DeformChecksum(source.Scene);
        var proofs=ProjectStore.PreservedSourcePaths(source).ToDictionary(path=>path,ProjectStore.Hash);doc.PinControls(setup,setup.Chains.Select(c=>c.Role).ToArray(),EditorPinBehavior.SoftReach);
        float length=PoseGeometry.Scale(source.Scene,setup);var requested=before.Local[body] with{Translation=before.Local[body].Translation+(setup.Axes?.Up??Vector3.UnitY)*length*1.5f+(setup.Axes?.Right??Vector3.UnitX)*length*.5f};
        var solved=EditorControlPosing.Solve(source.Scene,before,setup,new Dictionary<int,Transform>{{body,requested}},doc.CurrentContacts);check(solved.Value is not null,"The supplied native rig's simultaneous hand/foot soft pins solve the edited hip without replacing its skeleton");
        using(var edit=doc.BeginTransformEdit())check(edit.Commit(solved.Value!.Transforms),"The supplied native control pose commits to its existing animation channels");
        check(doc.Evaluate().Local[body]==requested&&AnimationControls.DeformChecksum(doc.Project.Scene)==native,"Native body translation remains exact and imported deform/bind data remain unchanged");
        await ProjectStore.SaveAsync(source,Path.Combine(output,"source.fighterport"));await ProjectStore.SaveAsync(doc.Project,Path.Combine(output,"target.fighterport"));var reopened=await ProjectStore.LoadAsync(Path.Combine(output,"target.fighterport"));var pose=AnimationService.Evaluate(reopened.Scene,reopened.Clips[0],0);
        check(Enumerable.Range(0,pose.World.Length).All(b=>Vector3.Distance(pose.World[b].Translation,doc.Evaluate().World[b].Translation)<.0001f),"The supplied native pose reopens with every saved joint position intact");
        check(proofs.All(pair=>ProjectStore.Hash(pair.Key)==pair.Value),"Supplied native model and animation source bytes remain immutable after control editing and save/reopen");
        await File.WriteAllTextAsync(Path.Combine(output,"native-control-evidence.json"),JsonSerializer.Serialize(new{Setup=setup.Id,setup.SkeletonFingerprint,Chains=setup.Chains.Length,Diagnostics=solved.Diagnostics,NativeInputBytesUnchanged=true,NativeOutputWritten=false,GameTested=false}));
    }
    static (FighterProject Project,ControlRigSetup Setup) Fixture(float unit=1,bool renamed=false)
    {
        string[] names=renamed?["a","b","c","d","e"]:["root","hip","upper","middle","end"];
        var scene=new Scene("Original soft-control fixture",[new(names[0],-1,Transform.Identity),new(names[1],0,Transform.Identity),new(names[2],1,Transform.Identity),new(names[3],2,new(Vector3.One,new(0,0,60),new(0,-unit,0))),new(names[4],3,new(Vector3.One,Vector3.Zero,new(0,-unit,0)))],[]);
        var setup=new ControlRigSetup(Guid.NewGuid(),AnimationControls.Fingerprint(scene),[],[]){BodyBone=1};setup=AnimationControls.ReviewChain(scene,setup,"Foot.L",2,3,4,Vector3.UnitZ,"Original analytic direct two-link fixture").Value!;
        return(new(1,Guid.NewGuid(),"Original controls",scene,[new(Guid.NewGuid(),"Motion",24,new(60),false,[])]){ControlRigs=[setup]},setup);
    }
    public static async Task RunAsync(string output,Action<bool,string> check)
    {
        await CreationAndPrecisionAsync(output,check);
        var (project,setup)=Fixture();var scene=project.Scene;var input=AnimationService.Evaluate(scene,null,0);string deform=AnimationControls.DeformChecksum(scene);var chain=setup.Chains.Single();var pin=ContactSolver.Capture(scene,input,setup,chain.Role) with{EditorBehavior=EditorPinBehavior.SoftReach};
        Dictionary<int,Transform> Hip(Vector3 delta)=>new(){{1,input.Local[1] with{Translation=input.Local[1].Translation+delta}}};
        var near=EditorControlPosing.Solve(scene,input,setup,Hip(new(.05f,0,0)),[pin]);check(near.Value is not null,"A reachable soft pin solves on the existing native chain");var nearPose=AnimationService.Evaluate(scene,null,0,near.Value!.Transforms);
        check(Vector3.Distance(nearPose.World[4].Translation,pin.Position)<.0001f&&nearPose.Local[1].Translation==new Vector3(.05f,0,0),"A reachable hand/foot anchor stays in place while the requested hip edit remains exact");
        var far=EditorControlPosing.Solve(scene,input,setup,Hip(new(5,0,0)),[pin]);check(far.Value is not null,"A soft pin yields when the fixed edited hip makes its old anchor unreachable");var farPose=AnimationService.Evaluate(scene,null,0,far.Value!.Transforms);var origin=new Vector3(5,0,0);var expected=origin+Vector3.Normalize(pin.Position-origin)*2;
        check(Vector3.Distance(farPose.World[4].Translation,expected)<.0001f&&farPose.Local[1].Translation==origin,"The yielded joint is the independently computed nearest point on the two-unit native reach sphere, without pulling the hip back");
        check(Math.Abs(Vector3.Distance(farPose.World[2].Translation,farPose.World[3].Translation)-1)<.0001f&&Math.Abs(Vector3.Distance(farPose.World[3].Translation,farPose.World[4].Translation)-1)<.0001f&&AnimationControls.DeformChecksum(scene)==deform,"Soft yielding preserves both native segment lengths, rests, hierarchy and deform data");
        check(far.Diagnostics.Any(d=>d.Code=="EDITOR_SOFT_PIN_YIELDED")&&pin.Position==input.World[4].Translation,"Yielding is reported without silently rewriting the authored anchor");
        var hard=EditorControlPosing.Solve(scene,input,setup,Hip(new(5,0,0)),[pin with{EditorBehavior=EditorPinBehavior.Fixed}]);check(hard.Value is null&&hard.Diagnostics.Any(d=>d.Code=="PROVEN_INCOMPATIBLE"),"Existing fixed pins still reject proven unreachable hip edits instead of acquiring a soft policy");
        foreach(float unit in new[]{.1f,3f})
        {
            var (scaled,scaledSetup)=Fixture(unit,true);var pose=AnimationService.Evaluate(scaled.Scene,null,0);var soft=ContactSolver.Capture(scaled.Scene,pose,scaledSetup,chain.Role) with{EditorBehavior=EditorPinBehavior.SoftReach};var result=EditorControlPosing.Solve(scaled.Scene,pose,scaledSetup,new Dictionary<int,Transform>{{1,pose.Local[1] with{Translation=new(5*unit,0,0)}}},[soft]);
            check(result.Value is not null&&Vector3.Distance(AnimationService.Evaluate(scaled.Scene,null,0,result.Value.Transforms).World[4].Translation/unit,expected)<.0002f,"Soft reach is invariant to bone renaming and world scale "+unit);
        }
        var rootEdit=input.Local[2] with{Rotation=new(0,0,25)};var oneJoint=EditorControlPosing.Solve(scene,input,setup,new Dictionary<int,Transform>{{2,rootEdit}},[pin]);check(oneJoint.Value is not null,"Soft control supports an explicitly rotated upper joint");var onePose=AnimationService.Evaluate(scene,null,0,oneJoint.Value!.Transforms);var fixedPose=AnimationService.Evaluate(scene,null,0,new Dictionary<int,Transform>{{2,rootEdit}});var centre=fixedPose.World[3].Translation;var expectedSingle=centre+Vector3.Normalize(pin.Position-centre);
        check(onePose.Local[2]==rootEdit&&Vector3.Distance(onePose.World[4].Translation,expectedSingle)<.0001f,"A fixed upper joint leaves exactly the lower-link sphere available; soft yielding is the nearest point on that sphere");
        var bad=EditorControlPosing.Solve(scene,input,setup,Hip(Vector3.Zero).ToDictionary(e=>e.Key,e=>e.Value with{Scale=new(1,2,1)}),[pin]);check(bad.Value is null&&bad.Diagnostics.Any(d=>d.Code=="SOFT_PIN_SCALE"),"Unsupported nonuniform scales reject without normalization or native bind edits");
        var doc=new EditorDocument(project);doc.SelectedBone=1;doc.Seek(4);doc.PinControls(setup,[chain.Role],EditorPinBehavior.SoftReach);var before=doc.Project;var savedPin=doc.CurrentContacts.Single();
        using(var edit=doc.BeginTransformEdit()){var solved=EditorControlPosing.Solve(scene,doc.Evaluate(),setup,Hip(new(5,0,0)),[savedPin]);check(edit.Commit(solved.Value!.Transforms),"Soft control results commit through the normal automatic-key gesture");}
        check(doc.PoseOverrides.Count==0&&Vector3.Distance(doc.Evaluate().World[4].Translation,expected)<.0001f,"The pose remains in ordinary animation channels after preview overrides clear");var edited=doc.Project;doc.Seek(9);doc.Seek(4);check(Vector3.Distance(doc.Evaluate().World[4].Translation,expected)<.0001f,"Returning to the edited frame reads saved keys without rerunning a contact solver");doc.Undo();check(ReferenceEquals(doc.Project,before),"One Undo restores the exact pre-gesture clip, pin policy and native channels");doc.Redo();check(ReferenceEquals(doc.Project,edited),"Redo restores the stored result without recomputing soft reach");
        string path=Path.Combine(output,"soft-controls.fighterport");await ProjectStore.SaveAsync(doc.Project,path);var reopened=await ProjectStore.LoadAsync(path);var restored=new EditorDocument(reopened);restored.Seek(4);check(restored.CurrentContacts.Single().EditorBehavior==EditorPinBehavior.SoftReach&&Vector3.Distance(restored.Evaluate().World[4].Translation,expected)<.0001f,"Project save/reopen retains soft-pin policy and the keyed pose independently");
        var untouched=JsonSerializer.Serialize(pin with{EditorBehavior=EditorPinBehavior.Fixed},ProjectStore.Json);check(!untouched.Contains("EditorBehavior",StringComparison.Ordinal),"Legacy fixed-pin JSON omits the new default policy, preserving historical dependency hashes");
        var targetBefore=doc.Project;var active=doc.CurrentContacts.Single();var actual=doc.Evaluate();var newAnchor=new EditorPinTarget(actual.World[active.Bone].Translation,PoseGeometry.Rotation(actual.World[active.Bone]));using(var gesture=doc.BeginTransformEdit())check(gesture.Commit(new Dictionary<int,Transform>(),new Dictionary<Guid,EditorPinTarget>{{active.Id,newAnchor}}),"An explicitly moved soft handle can reanchor without an invented deform transform");check(doc.CurrentContacts.Single().Position==newAnchor.Position,"An explicit handle move saves its new soft anchor instead of snapping back on the next gesture");doc.Undo();check(ReferenceEquals(doc.Project,targetBefore),"Anchor and animation edits share the ordinary exact Undo contract");
        var overlapping=new EditorDocument(targetBefore with{Contacts=targetBefore.Contacts.Concat(targetBefore.Contacts).ToArray()});overlapping.Seek(4);overlapping.SelectedBone=1;
        using(var gesture=overlapping.BeginTransformEdit())check(gesture.Commit(new Dictionary<int,Transform>{{1,overlapping.Evaluate().Local[1] with{Translation=new(5.1f,0,0)}}}),"An ordinary keyed pose does not require unique contact IDs across overlapping historical intervals");
        bool ambiguousRejected=false;using(var gesture=overlapping.BeginTransformEdit())try{gesture.Commit(new Dictionary<int,Transform>(),new Dictionary<Guid,EditorPinTarget>{{active.Id,newAnchor}});}catch(InvalidDataException){ambiguousRejected=true;}check(ambiguousRejected,"Explicit reanchoring rejects an ambiguous overlapping handle instead of moving several authored contacts");
        await FollowAnimationAsync(output,check);
        var arbitrary=new EditorDocument(project);var pinBefore=arbitrary.Project;var bonePin=arbitrary.AddBonePin(0);check(arbitrary.CurrentBonePins.Single().Id==bonePin&&arbitrary.CurrentContacts.Length==0&&ReferenceEquals(arbitrary.Project.Scene,scene),"Any existing bone can receive an independently identified FK pin without inventing an IK chain or contact");check(arbitrary.AddBonePin(0)==bonePin&&arbitrary.CurrentBonePins.Length==1,"Adding the same bone pin selects its existing identity instead of duplicating handles");var pinProject=arbitrary.Project;arbitrary.Undo();check(ReferenceEquals(arbitrary.Project,pinBefore),"Adding an arbitrary bone pin has one exact Undo");arbitrary.Redo();check(ReferenceEquals(arbitrary.Project,pinProject),"Redo restores the same saved pin identity");string pinPath=Path.Combine(output,"bone-pins.fighterport");await ProjectStore.SaveAsync(arbitrary.Project,pinPath);var pinReopened=new EditorDocument(await ProjectStore.LoadAsync(pinPath));check(pinReopened.CurrentBonePins.Single().Id==bonePin,"Project storage reopens arbitrary bone pin identities against the same exact rig revision");arbitrary.RemoveEditorPin(bonePin);check(arbitrary.CurrentBonePins.Length==0&&arbitrary.Project.Scene==scene,"Removing a bone pin preserves its native bone and animation");arbitrary.Undo();check(arbitrary.CurrentBonePins.Single().Id==bonePin,"Undoing removal restores the same bone pin");
    }
    static async Task CreationAndPrecisionAsync(string output,Action<bool,string> check)
    {
        foreach(float unit in new[]{.1f,1f,3f})foreach(float angle in new[]{-.04f,.04f,179.96f})
        {
            var scene=new Scene("Original analytic angular fixture",[new("a",-1,Transform.Identity),new("b",0,Transform.Identity),new("c",1,new(Vector3.One,Vector3.Zero,new(unit,0,0))),new("d",2,new(Vector3.One,Vector3.Zero,new(unit,0,0)))],[]);
            var setup=AnimationControls.ReviewChain(scene,new(Guid.NewGuid(),AnimationControls.Fingerprint(scene),[],[]),"Hand.L",1,2,3,Vector3.UnitZ,"Original straight two-link fixture with declared unit axes").Value!;
            var pose=AnimationService.Evaluate(scene,null,0);double radians=angle*Math.PI/180;
            var goal=new Vector3((float)(2*unit*Math.Cos(radians)),(float)(2*unit*Math.Sin(radians)),0);
            var solved=AnimationControls.Solve(scene,pose,setup,setup.Chains.Single(),goal,Vector3.UnitZ*unit);
            check(solved.Value is not null&&Vector3.Distance(solved.Value.Achieved,goal)<unit*.00002f,"Analytic endpoint survives small/near-opposite rotations at "+angle+" degrees and unit "+unit);
        }
        var (project,rig)=Fixture();var model=new EditorDocument(project with{Clips=[]});model.SelectedBone=0;
        var fk=model.AddBonePin(0);model.PinControls(rig,[rig.Chains.Single().Role],EditorPinBehavior.SoftReach);
        var requested=model.Evaluate().Local[0] with{Translation=new(1.5f,.75f,0),Rotation=new(0,15,0)};
        using(var edit=model.BeginTransformEdit())edit.Commit(new Dictionary<int,Transform>{{0,requested}});
        var before=model.Project;var anchor=model.CurrentContacts.Single();
        model.CreateAnimation("Original authored pose",60,new(60),true);var created=model.Project;
        check(model.CurrentBonePins.Single().Id==fk&&model.CurrentContacts.Single().Id==anchor.Id&&model.CurrentContacts.Single().Position==anchor.Position&&model.Evaluate().Local[0]==requested,"First animation keeps existing editor handles, exact authored anchors and pose channels");
        model.Undo();check(ReferenceEquals(model.Project,before)&&model.Project.Clips.Length==0&&model.CurrentBonePins.Single().Clip is null&&model.CurrentContacts.Single().Id==anchor.Id,"One Undo restores the exact model-only pose and pin ownership before animation creation");
        model.Redo();model.Seek(59);check(ReferenceEquals(model.Project,created)&&model.CurrentContacts.Single().Id==anchor.Id&&model.CurrentBonePins.Single().Id==fk&&model.Evaluate().Local[0]==requested,"Redo restores animation, controls and constant authored pose through the final sample");
        string path=Path.Combine(output,"created-pose-controls.fighterport");await ProjectStore.SaveAsync(model.Project,path);var reopened=new EditorDocument(await ProjectStore.LoadAsync(path));reopened.Seek(59);
        check(reopened.CurrentBonePins.Single().Id==fk&&reopened.CurrentContacts.Single().Position==anchor.Position&&reopened.Evaluate().Local[0]==requested,"Core project reopen keeps created-animation pin identities, unchanged anchors and authored channels");
    }
    static async Task FollowAnimationAsync(string output,Action<bool,string> check)
    {
        var (project,setup)=Fixture();var channels=new Curve?[9];channels[5]=new([new(0,0),new(10,90)],Interpolation.Linear);channels[6]=new([new(0,0),new(10,4)],Interpolation.Linear);var clip=project.Clips[0] with{Tracks=[new(project.Scene.Bones[0].Name,channels)]};project=project with{Clips=[clip]};var doc=new EditorDocument(project);doc.SelectedBone=1;doc.Seek(2);doc.PinControls(setup,["Foot.L"],EditorPinBehavior.SoftReach,true);var saved=doc.Project.Contacts.Single().Pins.Single();
        check(saved.EditorMotion is {OriginFrame:2} motion&&motion.Revision==clip.Revision&&doc.Project.Contacts.Single().EndFrame==clip.LastSampleFrame,"Follow-animation pins store the exact pre-edit motion revision and remain active from this frame through the clip end");
        var rest=AnimationService.Evaluate(project.Scene,null,0).World[4].Translation;
        Vector3 Expected(double frame)=>Vector3.Transform(rest,Matrix4x4.CreateRotationZ((float)frame*9*MathF.PI/180))+new Vector3((float)frame*.4f,0,0);
        doc.Seek(6.25);var current=doc.CurrentContacts.Single();check(Vector3.Distance(current.Position,Expected(6.25))<.00001f&&PoseGeometry.RotationDifference(current.Rotation,Quaternion.CreateFromAxisAngle(Vector3.UnitZ,116.25f*MathF.PI/180))<.05f,"A moving pin follows independently computed fractional translation and rotation, including the fixture's native sixty-degree distal rest orientation");
        var before=doc.Project;var requested=doc.Evaluate().Local[1] with{Translation=new(3,0,0)};var solved=EditorControlPosing.Solve(project.Scene,doc.Evaluate(),setup,new Dictionary<int,Transform>{{1,requested}},doc.CurrentContacts);check(solved.Value is not null,"Soft reach still solves a body edit against the animated reference anchor");using(var edit=doc.BeginTransformEdit())edit.Commit(solved.Value!.Transforms);
        check(Vector3.Distance(doc.CurrentContacts.Single().Position,Expected(6.25))<.00001f&&doc.Clip.Revision!=clip.Revision&&ReferenceEquals(saved.EditorMotion,doc.CurrentContacts.Single().EditorMotion),"New body keys cannot feed back into or recapture the pin's frozen animation reference");
        var offset=new Vector3(.2f,.3f,.4f);var targetRotation=Quaternion.CreateFromAxisAngle(Vector3.UnitY,.23f);var target=new EditorPinTarget(Expected(6.25)+offset,targetRotation);var beforeAnchor=doc.Project;using(var edit=doc.BeginTransformEdit())check(edit.Commit(new Dictionary<int,Transform>(),new Dictionary<Guid,EditorPinTarget>{{saved.Id,target}}),"A moving handle reanchors through the same owned transform command");
        check(Vector3.Distance(doc.CurrentContacts.Single().Position,target.Position)<.00001f&&PoseGeometry.RotationDifference(doc.CurrentContacts.Single().Rotation,targetRotation)<.05f,"Reanchoring converts the displayed world position and rotation back to the frozen motion's offset");
        doc.Seek(8);var later=doc.CurrentContacts.Single();check(Vector3.Distance(later.Position,Expected(8)+offset)<.00001f,"The moved handle retains its authored offset while its original animation keeps moving");
        var rateChanged=doc.Clip with{Rate=new(120)};var sameSeconds=new EditorDocument(doc.Project with{Clips=[rateChanged]});sameSeconds.Seek(16);check(Vector3.Distance(sameSeconds.CurrentContacts.Single().Position,later.Position)<.00001f,"Moving pins sample their stored native timebase rather than assuming the edited clip's frame rate");
        string path=Path.Combine(output,"moving-pins.fighterport");await ProjectStore.SaveAsync(doc.Project,path);var reopened=new EditorDocument(await ProjectStore.LoadAsync(path));reopened.Seek(8);check(Vector3.Distance(reopened.CurrentContacts.Single().Position,later.Position)<.00001f&&PoseGeometry.RotationDifference(reopened.CurrentContacts.Single().Rotation,later.Rotation)<.05f,"Project save/reopen preserves animated pin curves, timebase and explicit position/rotation offsets");
        doc.Undo();check(ReferenceEquals(doc.Project,beforeAnchor),"One Undo restores the exact animated anchor and existing keyed body pose");doc.Undo();check(ReferenceEquals(doc.Project,before),"A separate Undo restores the animation before the soft-pinned body edit");doc.Redo();doc.Redo();doc.Seek(8);
        var hand=saved with{Id=Guid.NewGuid(),Role="Hand.L"};doc.Transaction("Original other-role fixture",p=>p with{Contacts=p.Contacts.Append(new(Guid.NewGuid(),clip.Id,0,doc.SceneFingerprint,[hand]){EndFrame=clip.LastSampleFrame}).ToArray()});doc.PinControls(setup,["Foot.L"],EditorPinBehavior.SoftReach,false);var world=doc.CurrentContacts.Single(p=>p.Role=="Foot.L").Position;check(doc.CurrentContacts.Count(p=>p.Role=="Foot.L")==1&&doc.CurrentContacts.Any(p=>p.Role=="Hand.L"),"Re-pinning replaces only the chosen limb's future interval without duplicating active handles or removing other roles");doc.Seek(6.25);check(Vector3.Distance(doc.CurrentContacts.Single(p=>p.Role=="Foot.L").Position,Expected(6.25)+offset)<.00001f,"Re-pinning preserves the earlier moving-pin interval");doc.Seek(9);check(doc.CurrentContacts.Single(p=>p.Role=="Foot.L") is {EditorMotion:null} fixedWorld&&fixedWorld.Position==world,"World-space soft pins remain available alongside follow-animation pins");
        check(ReferenceEquals(project.Clips[0],clip)&&clip.Tracks[0].Channels[6]!.Sample(6.25)==2.5f,"The captured source animation remains immutable after all pin, body, offset and interval edits");
    }
}
